-- Migration-owned Oracle triggers.
CREATE OR REPLACE TRIGGER AGORA_ACCESS_REQUEST_GUARD
BEFORE INSERT OR UPDATE OR DELETE ON TB_TA_AGORA_ACCESS_REQUEST
FOR EACH ROW
DECLARE
    current_owner TB_TA_AGORA_DASHBOARD.OWNER_ID%TYPE;
    dashboard_state NVARCHAR2(16);
    owner_active NUMBER(1);
    requester_active NUMBER(1);
BEGIN
    IF DELETING THEN
        raise_application_error(-20023, 'access requests are retained');
    END IF;

    SELECT d.owner_id, d.state, u.is_active
    INTO current_owner, dashboard_state, owner_active
    FROM TB_TA_AGORA_DASHBOARD d
    JOIN TB_TA_AGORA_USER u ON u.id = d.owner_id
    WHERE d.id = :NEW.dashboard_id
    FOR UPDATE OF d.owner_id, u.is_active;

    SELECT is_active
    INTO requester_active
    FROM TB_TA_AGORA_USER
    WHERE id = :NEW.requester_id
    FOR UPDATE;

    IF INSERTING THEN
        IF :NEW.status <> 'pending'
           OR :NEW.resolved_at IS NOT NULL
           OR :NEW.resolved_by_id IS NOT NULL
           OR :NEW.requester_id = current_owner
           OR dashboard_state <> 'published'
           OR owner_active <> 1
           OR requester_active <> 1 THEN
            raise_application_error(-20023, 'new access request is invalid');
        END IF;
        RETURN;
    END IF;

    IF :NEW.id <> :OLD.id
       OR :NEW.dashboard_id <> :OLD.dashboard_id
       OR :NEW.requester_id <> :OLD.requester_id THEN
        raise_application_error(-20023, 'access-request scope is immutable');
    END IF;

    IF :OLD.status = 'pending' THEN
        IF :NEW.status = 'pending' THEN
            IF :NEW.requested_at <> :OLD.requested_at
               OR :NEW.resolved_at IS NOT NULL
               OR :NEW.resolved_by_id IS NOT NULL THEN
                raise_application_error(-20023, 'pending request time is immutable');
            END IF;
            RETURN;
        END IF;
        IF :NEW.status NOT IN ('approved', 'denied', 'cancelled')
           OR :NEW.resolved_at IS NULL
           OR :NEW.resolved_by_id IS NULL
           OR :NEW.requested_at <> :OLD.requested_at
           OR NVL(:NEW.message, CHR(0)) <> NVL(:OLD.message, CHR(0)) THEN
            raise_application_error(-20023, 'access-request resolution is invalid');
        END IF;
        IF (:NEW.status = 'cancelled' AND :NEW.resolved_by_id <> :NEW.requester_id)
           OR (
               :NEW.status IN ('approved', 'denied')
               AND :NEW.resolved_by_id <> current_owner
           ) THEN
            raise_application_error(-20023, 'access-request resolver is not authorized');
        END IF;
        IF :NEW.status = 'approved'
           AND (
               dashboard_state NOT IN ('published', 'unpublished')
               OR owner_active <> 1
               OR requester_active <> 1
           ) THEN
            raise_application_error(-20023, 'access request cannot be approved now');
        END IF;
        RETURN;
    END IF;

    IF :NEW.status = 'pending' THEN
        IF :NEW.requested_at <= :OLD.requested_at
           OR :NEW.resolved_at IS NOT NULL
           OR :NEW.resolved_by_id IS NOT NULL
           OR :NEW.requester_id = current_owner
           OR dashboard_state <> 'published'
           OR owner_active <> 1
           OR requester_active <> 1 THEN
            raise_application_error(-20023, 'access-request reopen is invalid');
        END IF;
        RETURN;
    END IF;

    IF :NEW.status <> :OLD.status
       OR NVL(:NEW.message, CHR(0)) <> NVL(:OLD.message, CHR(0))
       OR :NEW.requested_at <> :OLD.requested_at
       OR :NEW.resolved_at <> :OLD.resolved_at
       OR :NEW.resolved_by_id <> :OLD.resolved_by_id THEN
        raise_application_error(-20023, 'resolved access request is immutable until reopened');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        raise_application_error(-20023, 'access-request target is missing');
END;
/
CREATE OR REPLACE TRIGGER AGORA_ANALYTICS_CKPT_GUARD
BEFORE UPDATE OR DELETE ON TB_TA_AGORA_ANALYTICS_CKPT
FOR EACH ROW
BEGIN
    IF DELETING THEN
        raise_application_error(-20028, 'analytics checkpoint is retained');
    END IF;
    IF :NEW.pipeline_key <> :OLD.pipeline_key
       OR :NEW.last_completed_open_id < :OLD.last_completed_open_id THEN
        raise_application_error(-20028, 'analytics checkpoint cannot move backward');
    END IF;
END;
/
CREATE OR REPLACE TRIGGER agora_artifact_immut_guard
    BEFORE UPDATE OR DELETE ON TB_TA_AGORA_ARTIFACT
    FOR EACH ROW
    BEGIN
        raise_application_error(-20005, 'artifact rows are append-only');
    END;
/
CREATE OR REPLACE TRIGGER agora_artifact_insert_guard
    BEFORE INSERT ON TB_TA_AGORA_ARTIFACT
    FOR EACH ROW
    DECLARE
        parent_locked NUMBER(1);
    BEGIN
        IF :NEW.logical_name <> COMPOSE(:NEW.logical_name)
           OR :NEW.name_key <> COMPOSE(:NEW.name_key)
           OR :NEW.name_key <> NLS_LOWER(:NEW.name_key) THEN
            raise_application_error(-20004, 'artifact names must be canonical');
        END IF;
        SELECT artifacts_locked
        INTO parent_locked
        FROM TB_TA_AGORA_REVISION
        WHERE id = :NEW.revision_id;
        IF parent_locked <> 0 THEN
            raise_application_error(-20004, 'artifacts cannot be added to a complete revision');
        END IF;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            raise_application_error(-20004, 'artifact revision does not exist');
    END;
/
CREATE OR REPLACE TRIGGER agora_audit_append_guard
    BEFORE INSERT OR UPDATE OR DELETE ON TB_TA_AGORA_AUDIT_EVENT
    FOR EACH ROW
    DECLARE
        document JSON_ELEMENT_T;
    BEGIN
        IF UPDATING OR DELETING THEN
            raise_application_error(-20007, 'audit events are append-only');
        END IF;
        document := JSON_ELEMENT_T.parse(:NEW.metadata);
        IF NOT document.is_object THEN
            raise_application_error(-20007, 'audit metadata must be a JSON object');
        END IF;
    END;
/
CREATE OR REPLACE TRIGGER AGORA_AUTH_OPEN_GUARD
BEFORE INSERT OR UPDATE OR DELETE ON TB_TA_AGORA_AUTHORIZED_OPEN
FOR EACH ROW
DECLARE
    source_audience NVARCHAR2(8);
    source_dashboard TB_TA_AGORA_RENDER_AUTHORIZATION.DASHBOARD_ID%TYPE;
    source_viewer TB_TA_AGORA_RENDER_AUTHORIZATION.VIEWER_ID%TYPE;
    source_revision TB_TA_AGORA_RENDER_AUTHORIZATION.REVISION_ID%TYPE;
    source_grant TB_TA_AGORA_RENDER_AUTHORIZATION.VIEWER_GRANT_ID%TYPE;
    source_owner_epoch TB_TA_AGORA_RENDER_AUTHORIZATION.OWNER_TRANSFER_EPOCH_ID%TYPE;
    source_publication_version NUMBER(19);
    source_created_at TIMESTAMP WITH TIME ZONE;
    source_captured_at TIMESTAMP WITH TIME ZONE;
    source_revoked_at TIMESTAMP WITH TIME ZONE;
    source_viewer_auth_version NUMBER(19);
    viewer_active NUMBER(1);
    viewer_auth_version NUMBER(19);
    dashboard_owner TB_TA_AGORA_DASHBOARD.OWNER_ID%TYPE;
    dashboard_owner_epoch TB_TA_AGORA_DASHBOARD.LAST_OWNERSHIP_TRANSFER_ID%TYPE;
    dashboard_state NVARCHAR2(16);
    dashboard_revision TB_TA_AGORA_DASHBOARD.PUBLISHED_REVISION_ID%TYPE;
    dashboard_publication_version NUMBER(19);
    valid_grants NUMBER;
    checkpoint_open_id NUMBER(19);
BEGIN
    IF INSERTING THEN
        SELECT authorization.audience,
               authorization.dashboard_id,
               authorization.viewer_id,
               authorization.revision_id,
               authorization.viewer_grant_id,
               authorization.owner_transfer_epoch_id,
               authorization.publication_version,
               authorization.created_at,
               authorization.authorized_open_captured_at,
               authorization.revoked_at,
               authorization.viewer_auth_version,
               viewer.is_active,
               viewer.auth_version
        INTO source_audience,
             source_dashboard,
             source_viewer,
             source_revision,
             source_grant,
             source_owner_epoch,
             source_publication_version,
             source_created_at,
             source_captured_at,
             source_revoked_at,
             source_viewer_auth_version,
             viewer_active,
             viewer_auth_version
        FROM TB_TA_AGORA_RENDER_AUTHORIZATION authorization
        JOIN TB_TA_AGORA_USER viewer ON viewer.id = authorization.viewer_id
        WHERE authorization.id = :NEW.source_authorization_id
        FOR UPDATE OF authorization.authorized_open_captured_at;

        SELECT owner_id,
               last_ownership_transfer_id,
               state,
               published_revision_id,
               publication_version
        INTO dashboard_owner,
             dashboard_owner_epoch,
             dashboard_state,
             dashboard_revision,
             dashboard_publication_version
        FROM TB_TA_AGORA_DASHBOARD
        WHERE id = source_dashboard;

        IF source_audience <> 'viewer'
           OR source_captured_at IS NOT NULL
           OR source_revoked_at IS NOT NULL
           OR viewer_active <> 1
           OR source_viewer_auth_version <> viewer_auth_version
           OR source_publication_version IS NULL
           OR dashboard_state <> 'published'
           OR dashboard_revision <> source_revision
           OR dashboard_publication_version <> source_publication_version
           OR :NEW.dashboard_id <> source_dashboard
           OR :NEW.viewer_id <> source_viewer
           OR :NEW.revision_id <> source_revision
           OR :NEW.publication_version <> source_publication_version
           OR :NEW.opened_at <> source_created_at
           OR :NEW.aggregated_at IS NOT NULL THEN
            raise_application_error(-20025, 'authorized-open source is invalid');
        END IF;

        IF source_viewer <> dashboard_owner THEN
            IF source_grant IS NULL OR source_owner_epoch IS NOT NULL THEN
                raise_application_error(-20025, 'authorized-open viewer grant is missing');
            END IF;
            SELECT COUNT(*)
            INTO valid_grants
            FROM TB_TA_AGORA_VIEWER_GRANT
            WHERE id = source_grant
              AND dashboard_id = source_dashboard
              AND viewer_id = source_viewer
              AND revoked_at IS NULL;
            IF valid_grants <> 1 THEN
                raise_application_error(-20025, 'authorized-open viewer grant is invalid');
            END IF;
        ELSIF source_grant IS NOT NULL
           OR (source_owner_epoch IS NULL AND dashboard_owner_epoch IS NOT NULL)
           OR (source_owner_epoch IS NOT NULL AND dashboard_owner_epoch IS NULL)
           OR source_owner_epoch <> dashboard_owner_epoch THEN
            raise_application_error(-20025, 'owner authorized-open cannot bind a grant');
        END IF;
        RETURN;
    END IF;

    IF UPDATING THEN
        IF :NEW.id <> :OLD.id
           OR :NEW.source_authorization_id <> :OLD.source_authorization_id
           OR :NEW.dashboard_id <> :OLD.dashboard_id
           OR :NEW.viewer_id <> :OLD.viewer_id
           OR :NEW.revision_id <> :OLD.revision_id
           OR :NEW.publication_version <> :OLD.publication_version
           OR :NEW.opened_at <> :OLD.opened_at THEN
            raise_application_error(-20025, 'authorized-open source fields are immutable');
        END IF;
        IF :OLD.aggregated_at IS NOT NULL
           AND (
               :NEW.aggregated_at IS NULL
               OR :NEW.aggregated_at <> :OLD.aggregated_at
           ) THEN
            raise_application_error(-20025, 'authorized-open aggregation is one-way');
        END IF;
        RETURN;
    END IF;

    IF :OLD.aggregated_at IS NULL
       OR :OLD.opened_at > SYSTIMESTAMP - NUMTODSINTERVAL(90, 'DAY') THEN
        raise_application_error(-20025, 'authorized-open is not retention eligible');
    END IF;
    SELECT last_completed_open_id
    INTO checkpoint_open_id
    FROM TB_TA_AGORA_ANALYTICS_CKPT
    WHERE pipeline_key = 'authorized_opens_v1';
    IF :OLD.id > checkpoint_open_id THEN
        raise_application_error(-20025, 'authorized-open is ahead of checkpoint');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        raise_application_error(-20025, 'authorized-open dependency is missing');
END;
/
CREATE OR REPLACE TRIGGER AGORA_AUTH_OPEN_MARK
FOR INSERT ON TB_TA_AGORA_AUTHORIZED_OPEN
COMPOUND TRIGGER
    TYPE authorization_ids IS TABLE OF TB_TA_AGORA_AUTHORIZED_OPEN.SOURCE_AUTHORIZATION_ID%TYPE INDEX BY PLS_INTEGER;
    TYPE opened_times IS TABLE OF TIMESTAMP WITH TIME ZONE INDEX BY PLS_INTEGER;
    pending_authorizations authorization_ids;
    pending_times opened_times;
    pending_count PLS_INTEGER := 0;

    AFTER EACH ROW IS
    BEGIN
        pending_count := pending_count + 1;
        pending_authorizations(pending_count) := :NEW.source_authorization_id;
        pending_times(pending_count) := :NEW.opened_at;
    END AFTER EACH ROW;

    AFTER STATEMENT IS
    BEGIN
        FOR position IN 1 .. pending_count LOOP
            UPDATE TB_TA_AGORA_RENDER_AUTHORIZATION
            SET authorized_open_captured_at = pending_times(position)
            WHERE id = pending_authorizations(position)
              AND authorized_open_captured_at IS NULL;
            IF SQL%ROWCOUNT <> 1 THEN
                raise_application_error(-20026, 'authorized-open source was already captured');
            END IF;
        END LOOP;
    END AFTER STATEMENT;
END;
/
CREATE OR REPLACE TRIGGER AGORA_DASHBOARD_GUARD
BEFORE INSERT OR UPDATE OR DELETE ON TB_TA_AGORA_DASHBOARD
FOR EACH ROW
DECLARE
    description_changed BOOLEAN := FALSE;
    marker_dashboard TB_TA_AGORA_DASH_TRANSFER.DASHBOARD_ID%TYPE;
    marker_from_owner TB_TA_AGORA_DASH_TRANSFER.FROM_OWNER_ID%TYPE;
    marker_to_owner TB_TA_AGORA_DASH_TRANSFER.TO_OWNER_ID%TYPE;
    marker_previous TB_TA_AGORA_DASH_TRANSFER.PREVIOUS_TRANSFER_ID%TYPE;
    incoming_active_grants NUMBER;
    incoming_pending_requests NUMBER;
    outgoing_owner_active NUMBER(1);
    incoming_owner_active NUMBER(1);
BEGIN
    IF DELETING THEN
        raise_application_error(-20002, 'dashboards cannot be hard-deleted');
    END IF;
    IF INSERTING THEN
        IF :NEW.state <> 'draft'
           OR :NEW.latest_revision_id IS NOT NULL
           OR :NEW.published_revision_id IS NOT NULL
           OR :NEW.first_published_at IS NOT NULL
           OR :NEW.last_ownership_transfer_id IS NOT NULL THEN
            raise_application_error(-20002, 'new dashboards must begin as private drafts');
        END IF;
        RETURN;
    END IF;
    IF :NEW.id <> :OLD.id THEN
        raise_application_error(-20002, 'dashboard identity is immutable');
    END IF;

    IF :NEW.owner_id <> :OLD.owner_id THEN
        IF :OLD.state NOT IN ('draft', 'published', 'unpublished')
           OR :NEW.state <> :OLD.state
           OR :NEW.last_ownership_transfer_id IS NULL
           OR :NEW.last_ownership_transfer_id = :OLD.last_ownership_transfer_id THEN
            raise_application_error(-20002, 'ownership transfer state is invalid');
        END IF;
        IF :NEW.name <> :OLD.name
           OR :NEW.latest_revision_id <> :OLD.latest_revision_id
           OR (:NEW.latest_revision_id IS NULL AND :OLD.latest_revision_id IS NOT NULL)
           OR (:NEW.latest_revision_id IS NOT NULL AND :OLD.latest_revision_id IS NULL)
           OR :NEW.published_revision_id <> :OLD.published_revision_id
           OR (:NEW.published_revision_id IS NULL AND :OLD.published_revision_id IS NOT NULL)
           OR (:NEW.published_revision_id IS NOT NULL AND :OLD.published_revision_id IS NULL)
           OR :NEW.first_published_at <> :OLD.first_published_at
           OR (:NEW.first_published_at IS NULL AND :OLD.first_published_at IS NOT NULL)
           OR (:NEW.first_published_at IS NOT NULL AND :OLD.first_published_at IS NULL)
           OR :NEW.publication_version <> :OLD.publication_version
           OR :NEW.last_published_at <> :OLD.last_published_at
           OR (:NEW.last_published_at IS NULL AND :OLD.last_published_at IS NOT NULL)
           OR (:NEW.last_published_at IS NOT NULL AND :OLD.last_published_at IS NULL)
           OR NVL(:NEW.publication_note, CHR(0)) <> NVL(:OLD.publication_note, CHR(0))
           OR :NEW.data_as_of <> :OLD.data_as_of
           OR (:NEW.data_as_of IS NULL AND :OLD.data_as_of IS NOT NULL)
           OR (:NEW.data_as_of IS NOT NULL AND :OLD.data_as_of IS NULL)
           OR :NEW.freshness_interval_seconds <> :OLD.freshness_interval_seconds
           OR (
               :NEW.freshness_interval_seconds IS NULL
               AND :OLD.freshness_interval_seconds IS NOT NULL
           )
           OR (
               :NEW.freshness_interval_seconds IS NOT NULL
               AND :OLD.freshness_interval_seconds IS NULL
           )
           OR :NEW.freshness_confirmed_at <> :OLD.freshness_confirmed_at
           OR (:NEW.freshness_confirmed_at IS NULL AND :OLD.freshness_confirmed_at IS NOT NULL)
           OR (:NEW.freshness_confirmed_at IS NOT NULL AND :OLD.freshness_confirmed_at IS NULL)
           OR :NEW.stale_after <> :OLD.stale_after
           OR (:NEW.stale_after IS NULL AND :OLD.stale_after IS NOT NULL)
           OR (:NEW.stale_after IS NOT NULL AND :OLD.stale_after IS NULL)
           OR :NEW.created_at <> :OLD.created_at THEN
            raise_application_error(-20002, 'transfer must preserve dashboard state');
        END IF;
        IF :OLD.description IS NULL AND :NEW.description IS NOT NULL THEN
            description_changed := TRUE;
        ELSIF :OLD.description IS NOT NULL AND :NEW.description IS NULL THEN
            description_changed := TRUE;
        ELSIF :OLD.description IS NOT NULL
              AND DBMS_LOB.COMPARE(:OLD.description, :NEW.description) <> 0 THEN
            description_changed := TRUE;
        END IF;
        IF description_changed THEN
            raise_application_error(-20002, 'transfer must preserve dashboard description');
        END IF;

        SELECT dashboard_id, from_owner_id, to_owner_id, previous_transfer_id
        INTO marker_dashboard, marker_from_owner, marker_to_owner, marker_previous
        FROM TB_TA_AGORA_DASH_TRANSFER
        WHERE id = :NEW.last_ownership_transfer_id;

        IF marker_dashboard <> :OLD.id
           OR marker_from_owner <> :OLD.owner_id
           OR marker_to_owner <> :NEW.owner_id
           OR (marker_previous IS NULL AND :OLD.last_ownership_transfer_id IS NOT NULL)
           OR (marker_previous IS NOT NULL AND :OLD.last_ownership_transfer_id IS NULL)
           OR marker_previous <> :OLD.last_ownership_transfer_id THEN
            raise_application_error(-20002, 'ownership transfer marker is invalid');
        END IF;

        SELECT is_active
        INTO outgoing_owner_active
        FROM TB_TA_AGORA_USER
        WHERE id = :OLD.owner_id
        FOR UPDATE;
        SELECT is_active
        INTO incoming_owner_active
        FROM TB_TA_AGORA_USER
        WHERE id = :NEW.owner_id
        FOR UPDATE;
        IF outgoing_owner_active <> 1 OR incoming_owner_active <> 1 THEN
            raise_application_error(-20002, 'ownership transfer users must be active');
        END IF;

        SELECT COUNT(*)
        INTO incoming_active_grants
        FROM TB_TA_AGORA_VIEWER_GRANT
        WHERE dashboard_id = :OLD.id
          AND viewer_id = :NEW.owner_id
          AND revoked_at IS NULL;
        IF incoming_active_grants <> 0 THEN
            raise_application_error(-20002, 'incoming owner grant must be revoked');
        END IF;
        SELECT COUNT(*)
        INTO incoming_pending_requests
        FROM TB_TA_AGORA_ACCESS_REQUEST
        WHERE dashboard_id = :OLD.id
          AND requester_id = :NEW.owner_id
          AND status = 'pending';
        IF incoming_pending_requests <> 0 THEN
            raise_application_error(-20002, 'incoming owner request must be resolved');
        END IF;
        RETURN;
    END IF;

    IF (:NEW.last_ownership_transfer_id IS NULL AND :OLD.last_ownership_transfer_id IS NOT NULL)
       OR (:NEW.last_ownership_transfer_id IS NOT NULL AND :OLD.last_ownership_transfer_id IS NULL)
       OR :NEW.last_ownership_transfer_id <> :OLD.last_ownership_transfer_id THEN
        raise_application_error(-20002, 'transfer marker changes only with owner');
    END IF;
    IF :OLD.state = 'deleted' THEN
        raise_application_error(-20002, 'deleted dashboards are terminal tombstones');
    END IF;
    IF :OLD.first_published_at IS NOT NULL
       AND (
           :NEW.first_published_at IS NULL
           OR :NEW.first_published_at <> :OLD.first_published_at
       ) THEN
        raise_application_error(-20002, 'first publication time is immutable');
    END IF;
    IF :OLD.first_published_at IS NULL
       AND :NEW.first_published_at IS NOT NULL
       AND NOT (:OLD.state = 'draft' AND :NEW.state = 'published') THEN
        raise_application_error(-20002, 'publication history begins only with first publication');
    END IF;
    IF NOT (
        (:OLD.state = 'draft' AND :NEW.state IN ('draft', 'published', 'archived', 'deleted'))
        OR (
            :OLD.state = 'published'
            AND :NEW.state IN ('published', 'unpublished', 'archived', 'deleted')
        )
        OR (
            :OLD.state = 'unpublished'
            AND :NEW.state IN ('unpublished', 'published', 'archived', 'deleted')
        )
        OR (:OLD.state = 'archived' AND :NEW.state = 'deleted')
        OR (
            :OLD.state = 'archived'
            AND :OLD.first_published_at IS NULL
            AND :NEW.state = 'draft'
        )
        OR (
            :OLD.state = 'archived'
            AND :OLD.first_published_at IS NOT NULL
            AND :NEW.state = 'unpublished'
        )
    ) THEN
        raise_application_error(-20002, 'dashboard lifecycle transition is not allowed');
    END IF;
    IF :OLD.description IS NULL AND :NEW.description IS NOT NULL THEN
        description_changed := TRUE;
    ELSIF :OLD.description IS NOT NULL AND :NEW.description IS NULL THEN
        description_changed := TRUE;
    ELSIF :OLD.description IS NOT NULL
          AND DBMS_LOB.COMPARE(:OLD.description, :NEW.description) <> 0 THEN
        description_changed := TRUE;
    END IF;
    IF :OLD.state = 'archived'
       AND (
           :NEW.name <> :OLD.name
           OR description_changed
           OR :NEW.latest_revision_id <> :OLD.latest_revision_id
           OR (:NEW.latest_revision_id IS NULL AND :OLD.latest_revision_id IS NOT NULL)
           OR (:NEW.latest_revision_id IS NOT NULL AND :OLD.latest_revision_id IS NULL)
           OR :NEW.published_revision_id <> :OLD.published_revision_id
           OR (:NEW.published_revision_id IS NULL AND :OLD.published_revision_id IS NOT NULL)
           OR (:NEW.published_revision_id IS NOT NULL AND :OLD.published_revision_id IS NULL)
           OR :NEW.first_published_at <> :OLD.first_published_at
           OR (:NEW.first_published_at IS NULL AND :OLD.first_published_at IS NOT NULL)
           OR (:NEW.first_published_at IS NOT NULL AND :OLD.first_published_at IS NULL)
           OR :NEW.publication_version <> :OLD.publication_version
           OR :NEW.last_published_at <> :OLD.last_published_at
           OR (:NEW.last_published_at IS NULL AND :OLD.last_published_at IS NOT NULL)
           OR (:NEW.last_published_at IS NOT NULL AND :OLD.last_published_at IS NULL)
           OR NVL(:NEW.publication_note, CHR(0)) <> NVL(:OLD.publication_note, CHR(0))
           OR :NEW.data_as_of <> :OLD.data_as_of
           OR (:NEW.data_as_of IS NULL AND :OLD.data_as_of IS NOT NULL)
           OR (:NEW.data_as_of IS NOT NULL AND :OLD.data_as_of IS NULL)
           OR :NEW.freshness_interval_seconds <> :OLD.freshness_interval_seconds
           OR (
               :NEW.freshness_interval_seconds IS NULL
               AND :OLD.freshness_interval_seconds IS NOT NULL
           )
           OR (
               :NEW.freshness_interval_seconds IS NOT NULL
               AND :OLD.freshness_interval_seconds IS NULL
           )
           OR :NEW.freshness_confirmed_at <> :OLD.freshness_confirmed_at
           OR (:NEW.freshness_confirmed_at IS NULL AND :OLD.freshness_confirmed_at IS NOT NULL)
           OR (:NEW.freshness_confirmed_at IS NOT NULL AND :OLD.freshness_confirmed_at IS NULL)
           OR :NEW.stale_after <> :OLD.stale_after
           OR (:NEW.stale_after IS NULL AND :OLD.stale_after IS NOT NULL)
           OR (:NEW.stale_after IS NOT NULL AND :OLD.stale_after IS NULL)
           OR :NEW.created_at <> :OLD.created_at
       ) THEN
        raise_application_error(-20002, 'archived dashboards are read-only');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        raise_application_error(-20002, 'ownership transfer marker is missing');
END;
/
CREATE OR REPLACE TRIGGER agora_dashboard_latest_guard
    AFTER UPDATE OF latest_revision_id ON TB_TA_AGORA_DASHBOARD
    FOR EACH ROW
    DECLARE
        expected_latest VARCHAR2(32);
    BEGIN
        SELECT MAX(id) KEEP (DENSE_RANK LAST ORDER BY "NUMBER")
        INTO expected_latest
        FROM TB_TA_AGORA_REVISION
        WHERE dashboard_id = :NEW.id;
        IF :NEW.latest_revision_id <> expected_latest
           OR (:NEW.latest_revision_id IS NULL AND expected_latest IS NOT NULL)
           OR (:NEW.latest_revision_id IS NOT NULL AND expected_latest IS NULL) THEN
            raise_application_error(-20009, 'dashboard latest revision pointer is inconsistent');
        END IF;
    END;
/
CREATE OR REPLACE TRIGGER AGORA_DASH_META_GUARD
BEFORE INSERT OR UPDATE ON TB_TA_AGORA_DASHBOARD
FOR EACH ROW
BEGIN
    IF :NEW.freshness_interval_seconds IS NULL THEN
        IF :NEW.freshness_confirmed_at IS NOT NULL OR :NEW.stale_after IS NOT NULL THEN
            raise_application_error(-20021, 'freshness fields must be set together');
        END IF;
    ELSE
        IF :NEW.freshness_interval_seconds < 1
           OR :NEW.freshness_interval_seconds > 31536000
           OR :NEW.freshness_confirmed_at IS NULL
           OR :NEW.stale_after IS NULL THEN
            raise_application_error(-20021, 'freshness interval is invalid');
        END IF;
        IF :NEW.stale_after <>
           :NEW.freshness_confirmed_at
           + NUMTODSINTERVAL(:NEW.freshness_interval_seconds, 'SECOND') THEN
            raise_application_error(-20021, 'stale-after does not match freshness claim');
        END IF;
    END IF;

    IF (:NEW.publication_version = 0 AND :NEW.last_published_at IS NOT NULL)
       OR (:NEW.publication_version > 0 AND :NEW.last_published_at IS NULL) THEN
        raise_application_error(-20021, 'publication version and time do not match');
    END IF;

    IF INSERTING THEN
        IF :NEW.publication_version <> 0 OR :NEW.last_published_at IS NOT NULL THEN
            raise_application_error(-20021, 'new dashboards have no publication version');
        END IF;
        RETURN;
    END IF;

    IF :NEW.publication_version < :OLD.publication_version
       OR :NEW.publication_version > :OLD.publication_version + 1 THEN
        raise_application_error(-20021, 'publication version must advance by one');
    END IF;

    IF :NEW.publication_version = :OLD.publication_version + 1 THEN
        IF :NEW.state <> 'published'
           OR :NEW.published_revision_id IS NULL
           OR :NEW.last_published_at IS NULL
           OR (
               :OLD.last_published_at IS NOT NULL
               AND :NEW.last_published_at < :OLD.last_published_at
           ) THEN
            raise_application_error(-20021, 'publication version lacks a valid release');
        END IF;
    ELSE
        IF (:NEW.last_published_at IS NULL AND :OLD.last_published_at IS NOT NULL)
           OR (:NEW.last_published_at IS NOT NULL AND :OLD.last_published_at IS NULL)
           OR :NEW.last_published_at <> :OLD.last_published_at
           OR NVL(:NEW.publication_note, CHR(0)) <>
              NVL(:OLD.publication_note, CHR(0)) THEN
            raise_application_error(-20021, 'release metadata changes require a new version');
        END IF;
        IF :NEW.state = 'published'
           AND :OLD.state = 'published'
           AND (
               (:NEW.published_revision_id IS NULL AND :OLD.published_revision_id IS NOT NULL)
               OR (
                   :NEW.published_revision_id IS NOT NULL
                   AND :OLD.published_revision_id IS NULL
               )
               OR :NEW.published_revision_id <> :OLD.published_revision_id
           ) THEN
            raise_application_error(-20021, 'republish must advance publication version');
        END IF;
    END IF;
END;
/
CREATE OR REPLACE TRIGGER AGORA_GRANT_IMMUT_GUARD
BEFORE INSERT OR UPDATE OR DELETE ON TB_TA_AGORA_VIEWER_GRANT
FOR EACH ROW
DECLARE
    current_owner TB_TA_AGORA_DASHBOARD.OWNER_ID%TYPE;
    current_owner_active NUMBER(1);
BEGIN
    IF DELETING THEN
        raise_application_error(-20006, 'viewer grants cannot be deleted');
    END IF;
    SELECT dashboard.owner_id, owner_user.is_active
    INTO current_owner, current_owner_active
    FROM TB_TA_AGORA_DASHBOARD dashboard
    JOIN TB_TA_AGORA_USER owner_user ON owner_user.id = dashboard.owner_id
    WHERE dashboard.id = :NEW.dashboard_id
    FOR UPDATE OF dashboard.owner_id, owner_user.is_active;

    IF INSERTING THEN
        IF current_owner_active <> 1
           OR :NEW.created_by_id <> current_owner
           OR :NEW.viewer_id = current_owner THEN
            raise_application_error(-20006, 'grant creator must be the current owner');
        END IF;
        IF (:NEW.revoked_at IS NULL AND :NEW.revoked_by_id IS NOT NULL)
           OR (:NEW.revoked_at IS NOT NULL AND :NEW.revoked_by_id IS NULL) THEN
            raise_application_error(-20006, 'grant revocation fields do not match');
        END IF;
        IF :NEW.revoked_by_id IS NOT NULL
           AND :NEW.revoked_by_id <> current_owner THEN
            raise_application_error(-20006, 'grant revoker must be the current owner');
        END IF;
        RETURN;
    END IF;

    IF :NEW.id <> :OLD.id
       OR :NEW.dashboard_id <> :OLD.dashboard_id
       OR :NEW.viewer_id <> :OLD.viewer_id
       OR :NEW.created_by_id <> :OLD.created_by_id
       OR :NEW.created_at <> :OLD.created_at THEN
        raise_application_error(-20006, 'viewer grant relationship is immutable');
    END IF;
    IF :OLD.revoked_at IS NOT NULL THEN
        IF :NEW.revoked_at IS NULL
           OR :NEW.revoked_at <> :OLD.revoked_at
           OR :NEW.revoked_by_id IS NULL
           OR :OLD.revoked_by_id IS NULL
           OR :NEW.revoked_by_id <> :OLD.revoked_by_id THEN
            raise_application_error(-20006, 'viewer grant revocation is immutable');
        END IF;
        RETURN;
    END IF;
    IF :NEW.revoked_at IS NULL THEN
        IF :NEW.revoked_by_id IS NOT NULL THEN
            raise_application_error(-20006, 'grant revocation fields do not match');
        END IF;
        RETURN;
    END IF;
    IF current_owner_active <> 1
       OR :NEW.revoked_by_id IS NULL
       OR :NEW.revoked_by_id <> current_owner THEN
        raise_application_error(-20006, 'grant revoker must be the current owner');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        raise_application_error(-20006, 'grant dashboard is missing');
END;
/
CREATE OR REPLACE TRIGGER AGORA_RENDER_OPEN_GUARD
BEFORE UPDATE OF authorized_open_captured_at ON TB_TA_AGORA_RENDER_AUTHORIZATION
FOR EACH ROW
DECLARE
    matching_open NUMBER;
BEGIN
    IF (:NEW.authorized_open_captured_at IS NULL AND :OLD.authorized_open_captured_at IS NULL)
       OR :NEW.authorized_open_captured_at = :OLD.authorized_open_captured_at THEN
        RETURN;
    END IF;
    IF :OLD.authorized_open_captured_at IS NOT NULL
       OR :NEW.authorized_open_captured_at IS NULL
       OR :NEW.audience <> 'viewer'
       OR :NEW.authorized_open_captured_at <> :NEW.created_at THEN
        raise_application_error(-20027, 'render capture marker is immutable');
    END IF;
    SELECT COUNT(*)
    INTO matching_open
    FROM TB_TA_AGORA_AUTHORIZED_OPEN
    WHERE source_authorization_id = :NEW.id
      AND opened_at = :NEW.authorized_open_captured_at;
    IF matching_open <> 1 THEN
        raise_application_error(-20027, 'render capture marker lacks its source row');
    END IF;
END;
/
CREATE OR REPLACE TRIGGER agora_reservation_mut_guard
BEFORE UPDATE ON TB_TA_AGORA_STORAGE_RESERVATION
FOR EACH ROW
BEGIN
    IF :NEW.id <> :OLD.id
       OR :NEW.storage_key <> :OLD.storage_key
       OR :NEW.created_at <> :OLD.created_at
       OR :NEW.expires_at <> :OLD.expires_at THEN
        raise_application_error(-20010, 'storage reservation identity is immutable');
    END IF;
    IF :OLD.verified_size IS NOT NULL
       AND (
           :NEW.verified_size IS NULL
           OR :NEW.verified_size <> :OLD.verified_size
           OR :NEW.verified_sha256 IS NULL
           OR :NEW.verified_sha256 <> :OLD.verified_sha256
       ) THEN
        raise_application_error(-20010, 'storage verification receipt is immutable');
    END IF;
    IF :NEW.storage_state <> :OLD.storage_state
       AND NOT (
           :OLD.storage_state = 'reserved'
           AND :NEW.storage_state IN ('owned', 'collision')
       ) THEN
        raise_application_error(-20010, 'storage reservation state transition is not allowed');
    END IF;
    IF :OLD.cleanup_required = 1 AND :NEW.cleanup_required = 0 THEN
        raise_application_error(-20010, 'storage cleanup requirement cannot be cleared');
    END IF;
END;
/
CREATE OR REPLACE TRIGGER AGORA_REVISION_AUTH_GUARD
BEFORE INSERT ON TB_TA_AGORA_REVISION
FOR EACH ROW
DECLARE
    creator_active NUMBER(1);
    dashboard_state NVARCHAR2(16);
    current_owner TB_TA_AGORA_DASHBOARD.OWNER_ID%TYPE;
BEGIN
    SELECT state, owner_id
    INTO dashboard_state, current_owner
    FROM TB_TA_AGORA_DASHBOARD
    WHERE id = :NEW.dashboard_id
    FOR UPDATE;
    SELECT is_active
    INTO creator_active
    FROM TB_TA_AGORA_USER
    WHERE id = :NEW.created_by_id
    FOR UPDATE;
    IF creator_active <> 1 OR :NEW.created_by_id <> current_owner THEN
        raise_application_error(-20011, 'revision creator must be the active current owner');
    END IF;
    IF dashboard_state NOT IN ('draft', 'published', 'unpublished') THEN
        raise_application_error(-20011, 'dashboard state does not accept revisions');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        raise_application_error(-20011, 'revision authorization target is missing');
END;
/
CREATE OR REPLACE TRIGGER agora_revision_complete_guard
    AFTER UPDATE OF artifacts_locked ON TB_TA_AGORA_REVISION
    FOR EACH ROW
    DECLARE
        html_count NUMBER;
    BEGIN
        IF :OLD.artifacts_locked = 0 AND :NEW.artifacts_locked = 1 THEN
            SELECT COUNT(*)
            INTO html_count
            FROM TB_TA_AGORA_ARTIFACT
            WHERE revision_id = :NEW.id AND kind = 'html';
            IF html_count <> 1 THEN
                raise_application_error(
                    -20008,
                    'a committed revision requires exactly one HTML artifact'
                );
            END IF;
        END IF;
    END;
/
CREATE OR REPLACE TRIGGER agora_revision_immut_guard
    BEFORE UPDATE OR DELETE ON TB_TA_AGORA_REVISION
    FOR EACH ROW
    BEGIN
        IF DELETING THEN
            raise_application_error(-20003, 'complete revisions cannot be deleted');
        END IF;
        IF :OLD.artifacts_locked = 0
           AND :NEW.artifacts_locked = 1
           AND :NEW.id = :OLD.id
           AND :NEW.dashboard_id = :OLD.dashboard_id
           AND :NEW.number = :OLD.number
           AND :NEW.created_by_id = :OLD.created_by_id
           AND :NEW.created_at = :OLD.created_at THEN
            RETURN;
        END IF;
        raise_application_error(-20003, 'complete revisions are immutable');
    END;
/
CREATE OR REPLACE TRIGGER AGORA_TRANSFER_HISTORY_GUARD
BEFORE INSERT OR UPDATE OR DELETE ON TB_TA_AGORA_DASH_TRANSFER
FOR EACH ROW
DECLARE
    current_owner TB_TA_AGORA_DASHBOARD.OWNER_ID%TYPE;
    current_marker TB_TA_AGORA_DASHBOARD.LAST_OWNERSHIP_TRANSFER_ID%TYPE;
    dashboard_state NVARCHAR2(16);
    incoming_active NUMBER(1);
    outgoing_active NUMBER(1);
BEGIN
    IF UPDATING OR DELETING THEN
        raise_application_error(-20024, 'ownership transfer history is append-only');
    END IF;
    SELECT dashboard.owner_id,
           dashboard.last_ownership_transfer_id,
           dashboard.state,
           owner_user.is_active
    INTO current_owner, current_marker, dashboard_state, outgoing_active
    FROM TB_TA_AGORA_DASHBOARD dashboard
    JOIN TB_TA_AGORA_USER owner_user ON owner_user.id = dashboard.owner_id
    WHERE dashboard.id = :NEW.dashboard_id
    FOR UPDATE OF dashboard.owner_id, owner_user.is_active;
    SELECT is_active
    INTO incoming_active
    FROM TB_TA_AGORA_USER
    WHERE id = :NEW.to_owner_id
    FOR UPDATE;
    IF dashboard_state NOT IN ('draft', 'published', 'unpublished')
       OR :NEW.from_owner_id <> current_owner
       OR :NEW.to_owner_id = current_owner
       OR outgoing_active <> 1
       OR incoming_active <> 1
       OR (:NEW.previous_transfer_id IS NULL AND current_marker IS NOT NULL)
       OR (:NEW.previous_transfer_id IS NOT NULL AND current_marker IS NULL)
       OR :NEW.previous_transfer_id <> current_marker THEN
        raise_application_error(-20024, 'ownership transfer marker is invalid');
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        raise_application_error(-20024, 'ownership transfer target is missing');
END;
/
CREATE OR REPLACE TRIGGER agora_user_auth_version_guard
BEFORE UPDATE ON TB_TA_AGORA_USER
FOR EACH ROW
BEGIN
    IF :NEW.is_active <> :OLD.is_active
       AND :NEW.auth_version <= :OLD.auth_version THEN
        :NEW.auth_version := :OLD.auth_version + 1;
    END IF;
    IF :NEW.auth_version < :OLD.auth_version THEN
        raise_application_error(-20012, 'user authentication version cannot move backwards');
    END IF;
END;
/
CREATE OR REPLACE TRIGGER agora_user_retention_guard
    BEFORE UPDATE OR DELETE ON TB_TA_AGORA_USER
    FOR EACH ROW
    BEGIN
        IF DELETING THEN
            raise_application_error(-20001, 'users cannot be hard-deleted');
        END IF;
        IF :NEW.id <> :OLD.id OR :NEW.soeid <> :OLD.soeid THEN
            raise_application_error(-20001, 'user identity is immutable');
        END IF;
    END;
/
CREATE OR REPLACE TRIGGER AGORA_VIEW_STATE_GUARD
BEFORE INSERT OR UPDATE ON TB_TA_AGORA_DASH_VIEWER_STATE
FOR EACH ROW
DECLARE
    current_publication_version NUMBER(19);
BEGIN
    SELECT publication_version
    INTO current_publication_version
    FROM TB_TA_AGORA_DASHBOARD
    WHERE id = :NEW.dashboard_id;
    IF :NEW.seen_publication_version > current_publication_version THEN
        raise_application_error(-20022, 'seen version exceeds dashboard publication');
    END IF;
    IF INSERTING THEN
        RETURN;
    END IF;
    IF :NEW.id <> :OLD.id
       OR :NEW.user_id <> :OLD.user_id
       OR :NEW.dashboard_id <> :OLD.dashboard_id THEN
        raise_application_error(-20022, 'viewer-state scope is immutable');
    END IF;
    IF :NEW.last_viewed_at < :OLD.last_viewed_at
       OR :NEW.seen_publication_version < :OLD.seen_publication_version THEN
        raise_application_error(-20022, 'viewer state cannot move backward');
    END IF;
END;
/

